final class Counter {
    private let lock = NSLock()
    private var counts: [String: Int] = [:]

    func increment(_ key: String) {
        lock.lock()
        defer { lock.unlock() }          // every exit path releases
        counts[key, default: 0] += 1     // critical section
    }
}

